import 'package:flutter/material.dart'; import '../models/order.dart';
class OrderDetailScreen extends StatelessWidget{final CustomerOrder order;const OrderDetailScreen({super.key,required this.order});@override Widget build(BuildContext c){final states=OrderStatus.values.where((x)=>x!=OrderStatus.cancelled).toList();return Scaffold(appBar:AppBar(title:Text(order.id,style:const TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Order tracking',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:12),...states.map((s){final active=s.index<=order.status.index;return ListTile(contentPadding:EdgeInsets.zero,leading:Icon(active?Icons.check_circle:Icons.radio_button_unchecked,color:active?const Color(0xff0b7a53):Colors.grey),title:Text(s.label,style:TextStyle(fontWeight:active?FontWeight.w800:null));})]))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Items',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:8),...order.items.map((x)=>ListTile(contentPadding:EdgeInsets.zero,leading:Image.asset(x.product.imageAsset,width:48,height:48),title:Text(x.product.name),subtitle:Text('${x.product.unit} × ${x.quantity}'),trailing:Text('₹${x.total.round()}')),const Divider(),_r('Subtotal',order.subtotal),_r('Delivery',order.deliveryFee),_r('Total',order.total,bold:true)]))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Delivery address',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(order.address),const SizedBox(height:12),const Row(children:[Icon(Icons.payments_outlined),SizedBox(width:8),Text('Cash on Delivery')])])))]);}
